import {activityLabel} from '/activity-labels.js';
import {systemLogo} from '/core.js';
import {describeCourseIssues,milestoneDependencies} from '/authoring-diagnostics.js';
import {temporaryPasswordView,actionMenu,appearanceActions,uiIcon,api,applyTypography,bindLogin,cycleLocale,cycleTheme,esc,initLocale,initTheme,langButton,loginView,modal,setToken,t,themeIcon,toast} from '/core.js';
import {renderContent} from '/renderer.js';
import {ACTIVITY_TYPES as activityTypes,CONTENT_BLOCK_TYPES as blockTypes,RESULT_TYPES as resultTypes,WORKFLOW_NODE_TYPES as workflowTypes,PROJECTOR_THEMES,activitySpec} from '/capability-registry.js';
import {projectorContrastCheck,projectorPhaseForItem,renderProjectorFrame} from '/projector.js';
import {bindDiscovery,discoveryToolbar,refreshDiscoveries} from '/discovery.js';
initTheme();initLocale();
const app=document.querySelector('#app');
const state={user:null,settings:null,courses:[],courseId:Number(new URLSearchParams(location.search).get('course_id')||0),version:null,content:null,selection:null,tab:'tree',treeQuery:'',dirty:false,previewModule:0,previewMode:'trainer',previewPath:'',previewActivity:0,previewSafeArea:true,previewRoom:'normal',undo:[],redo:[],autosave:null,saving:false,lastSaved:null,readiness:null};
window.addEventListener('beforeunload',e=>{if(!state.dirty)return;e.preventDefault();e.returnValue=''});
async function boot(){const me=await api('/api/me').catch(()=>({user:null}));if(!me.user||me.user.role!=='trainer')return login();state.user=me.user;if(me.user.must_change_password)return temporaryPasswordView(app,me.user,async u=>{state.user=u;await load()});await load()}
function login(){setToken('');app.innerHTML=loginView({title:t('Course Builder'),subtitle:t('Sign in to continue')});bindLogin(app,{requiredRole:'trainer',onSuccess:async u=>{state.user=u;await load()},onLocaleChange:login})}
async function load(){const [s,ec]=await Promise.all([api('/api/settings'),api('/api/courses/editable')]);state.settings=s;state.courses=ec.courses||[];applyTypography(s.typography||{},'ui');if(!state.courseId&&state.courses[0])state.courseId=Number(state.courses[0].id);if(state.courseId&&!state.courses.some(c=>Number(c.id)===state.courseId)){toast(t('You do not have permission to edit this course.'),'error');state.courseId=state.courses[0]?.id||0}if(state.courseId)await openCourse();else renderEmpty()}
function renderEmpty(){app.innerHTML=`<div class="page"><div class="page-head"><div><h1>${esc(t('Course Builder'))}</h1><p>${esc(t('No editable courses are assigned to this account.'))}</p></div><a class="btn" href="/trainer">${esc(t('Back'))}</a></div></div>`}
async function openCourse(){const d=await api(`/api/courses/${state.courseId}`);let v=d.versions.find(x=>x.status==='draft');if(!v){const src=d.versions[0];if(!src){renderEmpty();return}const made=await api(`/api/courses/${state.courseId}/drafts`,{method:'POST',json:{source_version_id:src.id,version:nextVersion(src.version)}});v={id:made.version_id,version:made.version,status:'draft'}}const x=await api(`/api/course-versions/${v.id}/draft`);state.version=x.version;state.content=x.content;state.selection=null;state.dirty=false;state.undo=[];state.redo=[];state.lastSaved=new Date();state.previewModule=0;state.previewPath='';state.previewActivity=0;state.content.course??={};state.content.course.branding??={};if(!PROJECTOR_THEMES.includes(state.content.course.branding.projector_theme))state.content.course.branding.projector_theme='dark';await refreshReadiness();render()}
function nextVersion(v='1.0'){const m=String(v).match(/^(\d+)\.(\d+)/);return m?`${m[1]}.${Number(m[2])+1}`:`${v}.1`}
function mods(){return state.content?.course?.modules||[]}
function moduleAt(mi){return mods()[Number(mi)]||null}
function shell(body){
  const c=state.courses.find(x=>Number(x.id)===Number(state.courseId));
  const tools=['revisions','assets','templates','simulate','validate'].map((a,i)=>`<button class="one-menu-item" data-a="${a}"><span>${esc(t(['Revision history','Asset library','Reusable templates','Workflow simulator','Validation'][i]))}</span></button>`).join('');
  const menu=actionMenu(t('Menu'),`${appearanceActions('data-a')}<div class="one-menu-separator"></div><button class="one-menu-item" data-a="back-trainer">${esc(t('Trainer workspace'))}</button>`);
  return `<div class="page builder-page"><header class="builder-masthead"><a class="brand" href="/trainer">${systemLogo()}<span>ONE <small>${esc(t('Course Builder'))}</small></span></a><label class="builder-course-switch"><span class="sr-only">${esc(t('Course'))}</span><select class="select" id="coursePick">${state.courses.map(x=>`<option value="${x.id}" ${Number(x.id)===Number(state.courseId)?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label>${menu}</header><div class="page-head builder-heading"><div><div class="eyebrow">${esc(t('Course workspace'))}</div><h1>${esc(c?.title||'')}</h1><p>${esc(t('Draft'))} ${esc(state.version?.version||'')} · ${esc(t('Shape the learning journey, one milestone at a time.'))}</p></div></div><div class="builder-commandbar"><div class="builder-tabs"><button class="${state.tab==='tree'?'active':''}" data-tab="tree">${esc(t('Course flow'))}</button><button class="${state.tab==='edit'?'active':''}" data-tab="edit">${esc(t('Edit view'))}</button><button class="${state.tab==='preview'?'active':''}" data-tab="preview">${esc(t('Preview mode'))}</button></div><div class="builder-status"><span class="save-status-dot ${state.dirty?'pending':''}"></span><span class="tiny muted">${esc(state.saving?t('Saving…'):state.dirty?t('Unsaved changes'):t('All changes saved'))}</span><span class="badge ${state.readiness?.ready?'ok':''}">${esc(state.readiness?.ready?t('Ready to publish'):t('Draft'))}</span>${Number(state.readiness?.error_count||0)>0?`<button class="badge warn readiness-details" data-a="validate" type="button">${Number(state.readiness.error_count)} ${esc(t('Blockers'))}</button>`:''}</div><div class="builder-actions"><button class="btn icon" data-a="undo" aria-label="${esc(t('Undo'))}" ${state.undo.length?'':'disabled'}>↶</button><button class="btn icon" data-a="redo" aria-label="${esc(t('Redo'))}" ${state.redo.length?'':'disabled'}>↷</button>${actionMenu(t('Tools'),tools,{icon:'tools'})}<button class="btn" data-a="save">${esc(t('Save draft'))}</button><button class="btn primary" data-a="publish" ${!state.courses.find(c=>Number(c.id)===Number(state.courseId))?.can_publish||state.readiness&&!state.readiness.ready?'disabled':''} title="${esc(t(state.courses.find(c=>Number(c.id)===Number(state.courseId))?.can_publish?'Publish version':'Publishing permission is required for this course.'))}">${esc(t('Publish version'))}</button></div></div>${body}</div>`;
}
function render(){app.innerHTML=shell(state.tab==='tree'?tree():state.tab==='edit'?edit():preview());bind()}
function snapshot(){return JSON.stringify(state.content||null)}
function remember(){if(!state.content)return;const snap=snapshot();if(state.undo.at(-1)!==snap){state.undo.push(snap);if(state.undo.length>80)state.undo.shift()}state.redo=[]}
function tree(){return `<div class="workflow-shell"><section class="tree-panel"><div class="tree-toolbar builder-tree-searchbar"><label class="discovery-search"><span class="sr-only">${esc(t('Search'))}</span><span class="discovery-search-icon">⌕</span><input class="input" id="builderTreeSearch" type="search" value="${esc(state.treeQuery||'')}" placeholder="${esc(t('Search course flow'))}"></label><button class="btn primary" data-a="add-module">${uiIcon('add')}${esc(t('Add milestone'))}</button></div>${mods().map((m,mi)=>`<section class="tree-module" data-builder-tree-module data-search="${esc([m.title,m.description].filter(Boolean).join(' '))}"><div class="tree-module-head"><div class="tree-module-index">${String(mi+1).padStart(2,'0')}</div><button class="tree-module-title" data-select="module" data-mi="${mi}"><span class="tiny muted">${esc(t('Milestone'))}</span><strong>${esc(m.title||t('Untitled'))}</strong></button><div class="tree-node-actions">${actionMenu(t('Add'),['activity','mission','path'].map((kind,i)=>`<button class="one-menu-item" data-add="${kind}" data-mi="${mi}">${uiIcon('add')}<span>${esc(t(['Activity','Mission','Participant path'][i]))}</span></button>`).join(''),{icon:'add'})}${actionMenu(t('Milestone options'),`<button class="one-menu-item" data-select="module" data-mi="${mi}">${esc(t('Edit milestone'))}</button><button class="one-menu-item" data-workflow="${mi}">${esc(t('Workflow'))}</button><div class="one-menu-separator"></div><button class="one-menu-item danger" data-delete-milestone="${mi}">${esc(t('Delete milestone'))}</button>`,{icon:'more',compact:true})}</div></div><div class="tree-module-items">${rows('activity',m.activities||[],mi)}${rows('mission',m.missions||[],mi)}${rows('path',m.paths||[],mi)}</div><footer class="tree-module-foot">${(m.activities||[]).length} ${esc(t('Activities'))} · ${(m.missions||[]).length} ${esc(t('Missions'))} · ${(m.paths||[]).length} ${esc(t('Participant paths'))}</footer></section>`).join('')}</section><section class="editor-panel"><div class="metric-row"><div><div class="eyebrow">${esc(t('Workflow tree'))}</div><h2>${esc(t('Milestone journey'))}</h2></div><span class="badge">${esc(t('Visual model'))}</span></div>${workflowDiagram()}</section></div>`}
function rows(kind,arr,mi){return arr.map((x,i)=>{const attributes=`data-kind="${kind}" data-mi="${mi}" data-ii="${i}"`,name=kind==='activity'?(activityLabel(x.type)):t(kind==='mission'?'Mission':'Participant path');return `<div class="tree-node" data-builder-tree-node data-search="${esc([x.title,x.id,kind,x.type].filter(Boolean).join(' '))}"><span class="node-icon">${uiIcon(kind==='activity'?'tools':kind==='mission'?'add':'user')}</span><button class="tree-node-title" data-select="${kind}" data-mi="${mi}" data-ii="${i}"><strong>${esc(x.title||t('Untitled'))}</strong><small>${esc(t(name))}</small></button>${actionMenu(t('Item options'),`<button class="one-menu-item" data-move="up" ${attributes}>↑ <span>${esc(t('Move up'))}</span></button><button class="one-menu-item" data-move="down" ${attributes}>↓ <span>${esc(t('Move down'))}</span></button><button class="one-menu-item" data-copy="1" ${attributes}>${esc(t('Duplicate'))}</button><div class="one-menu-separator"></div><button class="one-menu-item danger" data-del="1" ${attributes}>${esc(t('Delete'))}</button>`,{icon:'more',compact:true})}</div>`}).join('')}

function workflowDiagram(){const mi=state.selection?.mi??0,m=moduleAt(mi)||mods()[0];if(!m)return `<div class="empty">${esc(t('Add milestone'))}</div>`;const wf=m.workflow||{nodes:[],edges:[]};if(!wf.nodes?.length){const sequence=[...(m.activities||[]).map(a=>({title:a.title,type:a.type||'activity'})),...(m.paths||[]).map(p=>({title:p.title,type:'participant_path'})),...(m.missions||[]).map(x=>({title:x.title,type:'mission'}))];return `<div class="workflow-canvas visual-workflow">${sequence.map((x,i)=>`${i?'<div class="workflow-arrow">↓</div>':''}<div class="workflow-node-card"><span class="badge">${esc(activityLabel(x.type))}</span><strong>${esc(x.title||'')}</strong></div>`).join('')||`<div class="empty">${esc(t('No activity yet.'))}</div>`}</div>`}const incoming=new Map();for(const e of wf.edges||[]){if(!incoming.has(e.to))incoming.set(e.to,[]);incoming.get(e.to).push(e)}return `<div class="workflow-canvas visual-workflow">${wf.nodes.map((n,i)=>`<div class="workflow-node-card ${n.id===wf.start_node_id?'workflow-start':''}"><div class="metric-row"><span class="badge">${esc(String(n.type||'node').replaceAll('_',' '))}</span>${n.id===wf.start_node_id?`<span class="tiny muted">${esc(t('Start'))}</span>`:''}</div><strong>${esc(n.title||resolveRefTitle(m,n)||t('Untitled'))}</strong>${incoming.get(n.id)?.length?`<div class="tiny muted">${incoming.get(n.id).map(e=>`${esc(e.scope||'class')} ← ${esc(e.from)}`).join('<br>')}</div>`:''}</div>${i<wf.nodes.length-1?'<div class="workflow-arrow">↓</div>':''}`).join('')}</div>`}
function resolveRefTitle(m,n){if(n.activity_id)return (m.activities||[]).find(x=>x.id===n.activity_id)?.title;if(n.path_id)return (m.paths||[]).find(x=>x.id===n.path_id)?.title;if(n.mission_id)return (m.missions||[]).find(x=>x.id===n.mission_id)?.title;return ''}
function conditionText(c){if(!c)return '';if(typeof c==='string')return c;try{return JSON.stringify(c)}catch{return ''}}
function parseConditionText(raw){const c=String(raw||'').trim();if(!c)return null;try{const v=JSON.parse(c);if(v&&typeof v==='object'&&!Array.isArray(v))return v}catch{}const m=c.match(/^([a-zA-Z0-9_.-]+)\s*=\s*(.+)$/);if(m)return {[m[1]]:m[2]};throw new Error(t('Condition must be JSON or key=value.'))}
function selected(){const s=state.selection;if(!s)return null;const m=moduleAt(s.mi);if(!m)return null;if(s.kind==='module')return m;if(s.kind==='workflow')return m.workflow||(m.workflow={start_node_id:'',nodes:[],edges:[]});return (s.kind==='activity'?m.activities:s.kind==='mission'?m.missions:m.paths)?.[s.ii]||null}
function edit(){const x=selected();if(!x)return `<div class="card empty">${esc(t('Choose an item from the course flow.'))}</div>`;const s=state.selection;if(s.kind==='module')return editModule(x);if(s.kind==='activity')return editActivity(x);if(s.kind==='mission')return editMission(x);if(s.kind==='path')return editPath(x);if(s.kind==='workflow')return editWorkflow(moduleAt(s.mi),x);return ''}
function editModule(m){return `<section class="card"><div class="page-head compact"><div><div class="eyebrow">${esc(t('Milestone'))}</div><h2>${esc(m.title||'')}</h2></div></div><div class="form-grid"><div class="field span-2"><label>${esc(t('Name'))}</label><input class="input" id="modTitle" value="${esc(m.title||'')}"></div><div class="field"><label>${esc(t('Duration (minutes)'))}</label><input class="input" id="modDuration" type="number" min="0" value="${Number(m.duration_minutes||0)}"></div><div class="field span-2"><label>${esc(t('Description'))}</label><textarea class="textarea" id="modDescription">${esc(m.description||'')}</textarea></div><div class="field span-2"><label>${esc(t('Objectives'))}</label><textarea class="textarea" id="modObjectives" placeholder="One objective per line">${esc((m.objectives||[]).map(o=>typeof o==='string'?o:o.title||o.id||'').join('\n'))}</textarea></div></div><div class="form-actions"><button class="btn primary" data-a="apply-module">${esc(t('Apply'))}</button></div></section>`}

function lines(v=''){return String(v||'').split(/\n/).map(x=>x.trim()).filter(Boolean)}
function genericActivitySettings(a){
  const type=a.type,c=a.content||(a.content={blocks:[]}),spec=activitySpec(type)||{};
  const section=(title,body,help='')=>`<section class="card flat activity-type-settings" style="margin-top:16px"><div class="eyebrow">${esc(t('Activity settings'))}</div><h3>${esc(t(title))}</h3>${help?`<p class="small muted">${esc(t(help))}</p>`:''}<div class="form-grid">${body}</div></section>`;
  const q=`<div class="field span-2"><label>${esc(t('Question'))}</label><input class="input" id="basicQuestion" value="${esc(c.question||'')}"></div>`;
  const opts=`<div class="field span-2"><label>${esc(t('Options'))}</label><textarea class="textarea" id="basicOptions" placeholder="Option A\nOption B">${esc((c.options||[]).map(o=>typeof o==='string'?o:o.label||o.value||'').join('\n'))}</textarea></div>`;
  if(type==='poll'||type==='reaction')return section(type==='poll'?'Poll settings':'Reaction settings',q+opts);
  if(type==='single_choice')return section('Single Choice settings',q+opts+`<div class="field"><label>${esc(t('Correct answer'))}</label><input class="input" id="basicCorrect" value="${esc(c.correct_answer??'')}"></div>`);
  if(type==='multiple_choice')return section('Multiple Choice settings',q+opts+`<div class="field span-2"><label>${esc(t('Correct answers'))}</label><input class="input" id="basicCorrectMany" value="${esc((c.correct_answers||[]).join(' | '))}" placeholder="A | C"></div>`);
  if(type==='true_false')return section('True / False settings',q+`<div class="field"><label>${esc(t('Correct answer'))}</label><select class="select" id="basicTrueFalse"><option value="" ${c.correct_answer==null?'selected':''}>—</option><option value="true" ${String(c.correct_answer)==='true'?'selected':''}>${esc(t('True'))}</option><option value="false" ${String(c.correct_answer)==='false'?'selected':''}>${esc(t('False'))}</option></select></div>`);
  if(['short_answer','long_answer','reflection','self_assessment','team_challenge'].includes(type))return section(type==='team_challenge'?'Team challenge settings':type==='reflection'?'Reflection settings':type==='self_assessment'?'Self-assessment settings':type==='long_answer'?'Long answer settings':'Short answer settings',q+`<div class="field span-2"><label>${esc(t('Placeholder'))}</label><input class="input" id="basicPlaceholder" value="${esc(c.placeholder||'')}"></div>`);
  if(type==='numeric_answer')return section('Numeric Answer settings',q+`<div class="field"><label>${esc(t('Correct answer'))}</label><input class="input" id="basicNumberCorrect" type="number" step="any" value="${c.correct_answer??''}"></div><div class="field"><label>${esc(t('Tolerance'))}</label><input class="input" id="basicTolerance" type="number" step="any" min="0" value="${c.tolerance??0}"></div><div class="field"><label>${esc(t('Minimum'))}</label><input class="input" id="basicMin" type="number" step="any" value="${c.min??''}"></div><div class="field"><label>${esc(t('Maximum'))}</label><input class="input" id="basicMax" type="number" step="any" value="${c.max??''}"></div><div class="field"><label>${esc(t('Step'))}</label><input class="input" id="basicStep" type="number" step="any" min="0" value="${c.step??''}"></div>`);
  if(type==='rating'||type==='confidence')return section(type==='confidence'?'Confidence settings':'Rating settings',q+`<div class="field"><label>${esc(t('Minimum'))}</label><input class="input" id="basicMin" type="number" value="${Number(c.min??1)}"></div><div class="field"><label>${esc(t('Maximum'))}</label><input class="input" id="basicMax" type="number" value="${Number(c.max??5)}"></div><div class="field"><label>${esc(t('Step'))}</label><input class="input" id="basicStep" type="number" min="0.01" step="any" value="${Number(c.step??1)}"></div><div class="field"><label>${esc(t('Minimum label'))}</label><input class="input" id="basicMinLabel" value="${esc(c.min_label||'')}"></div><div class="field"><label>${esc(t('Maximum label'))}</label><input class="input" id="basicMaxLabel" value="${esc(c.max_label||'')}"></div>`);
  if(type==='ranking')return section('Ranking settings',q+opts);
  if(type==='checklist')return section('Checklist settings',q+`<div class="field span-2"><label>${esc(t('Items'))}</label><textarea class="textarea" id="basicItems" placeholder="Item 1\nItem 2">${esc((c.items||[]).map(x=>typeof x==='string'?x:x.label||x.title||'').join('\n'))}</textarea></div>`);
  if(type==='timer')return section('Timer settings',`<div class="field"><label>${esc(t('Seconds'))}</label><input class="input" id="basicSeconds" type="number" min="1" max="86400" value="${Number(c.seconds||60)}"></div>`);
  if(['url_submission','file_submission','image_submission'].includes(type))return section(type==='url_submission'?'URL submission settings':type==='file_submission'?'File submission settings':'Image submission settings',q+`<div class="field span-2"><label>${esc(t('Instructions'))}</label><textarea class="textarea" id="basicInstructions">${esc(c.body_md||'')}</textarea></div>`);
  if(['presentation','announcement','reveal','participant_choice','practice_gate'].includes(type))return section(type==='presentation'?'Presentation settings':type==='announcement'?'Announcement settings':type==='reveal'?'Reveal settings':type==='participant_choice'?'Participant choice settings':'Practice gate settings','', 'Use the presentation content blocks below for this activity.');
  if(spec.response_model==='none')return section('Activity settings','', 'Use the presentation content blocks below for this activity.');
  return '';
}
function applyGenericActivitySettings(a,type){
  const c=a.content||(a.content={blocks:[]}),q=document.querySelector('#basicQuestion')?.value?.trim();if(q!==undefined){if(q)c.question=q;else delete c.question}
  const optEl=document.querySelector('#basicOptions');if(optEl)c.options=lines(optEl.value).slice(0,30);
  const correct=document.querySelector('#basicCorrect');if(correct){const v=correct.value.trim();if(v)c.correct_answer=v;else delete c.correct_answer}
  const correctMany=document.querySelector('#basicCorrectMany');if(correctMany)c.correct_answers=correctMany.value.split('|').map(x=>x.trim()).filter(Boolean);
  const tf=document.querySelector('#basicTrueFalse');if(tf){if(tf.value==='')delete c.correct_answer;else c.correct_answer=tf.value==='true'}
  const ph=document.querySelector('#basicPlaceholder');if(ph)c.placeholder=ph.value;
  const nc=document.querySelector('#basicNumberCorrect');if(nc){if(nc.value==='')delete c.correct_answer;else c.correct_answer=Number(nc.value)}
  const tol=document.querySelector('#basicTolerance');if(tol)c.tolerance=Math.max(0,Number(tol.value||0));
  for(const [id,key] of [['#basicMin','min'],['#basicMax','max'],['#basicStep','step']]){const el=document.querySelector(id);if(el){if(el.value==='')delete c[key];else c[key]=Number(el.value)}}
  const minLabel=document.querySelector('#basicMinLabel');if(minLabel)c.min_label=minLabel.value;const maxLabel=document.querySelector('#basicMaxLabel');if(maxLabel)c.max_label=maxLabel.value;
  const items=document.querySelector('#basicItems');if(items)c.items=lines(items.value).slice(0,40);
  const secs=document.querySelector('#basicSeconds');if(secs)c.seconds=Math.max(1,Math.min(86400,Number(secs.value||60)));
  const inst=document.querySelector('#basicInstructions');if(inst)c.body_md=inst.value;
}
function initializeActivityType(a,type,spec){
  const configKeys=['word_cloud','q_and_a','ideas_board','prioritization','quick_interaction','matching','fill_blanks','sorting','image_interaction','draw_annotate','collaborative_board','interactive_video'];
  for(const k of configKeys)delete a[k];
  a.type=type;if(spec?.participant_input)a.response_scope=type==='team_challenge'?'team':'individual';else delete a.response_scope;a.content??={blocks:[]};a.content.blocks??=[];const c=a.content;
  for(const key of ['options','correct_answer','correct_answers','min','max','step','tolerance','min_label','max_label','placeholder','items','seconds','image_asset','video_asset','pairs','blanks'])delete c[key];
  const defaults=spec?.defaults||{};
  if(spec?.participant_input&&!c.question)c.question=a.title||t('Activity');
  if(['poll','single_choice','multiple_choice','reaction','ranking'].includes(type))c.options=[];
  if(type==='true_false')c.options=[t('True'),t('False')];
  if(type==='rating'||type==='confidence'){c.min=1;c.max=5}
  if(type==='timer')c.seconds=60;
  if(type==='word_cloud')a.word_cloud={max_entries:3,max_characters:32,allow_phrases:true,moderation:'off',identity_visibility:'trainer_only',...defaults};
  if(type==='q_and_a')a.q_and_a={max_questions:3,max_characters:280,moderation:'pre',identity_visibility:'trainer_only',upvoting:true,allow_self_upvote:false,sort:'votes',...defaults};
  if(type==='ideas_board')a.ideas_board={max_ideas:5,max_characters:240,moderation:'pre',identity_visibility:'trainer_only',upvoting:true,allow_self_upvote:false,sort:'votes',categories:['Ideas'],...defaults};
  if(type==='prioritization_100'){a.prioritization={budget:100,require_full_allocation:true,max_per_option:100,...defaults};c.options=[]}
  if(type==='quick_interaction'){a.quick_interaction={preset:'understand',anonymous:true,...defaults};c.options=['Got it','Need help']}
  if(type==='matching'){a.matching={pairs:[],shuffle:true};c.pairs=[]}
  if(type==='fill_blanks'){a.fill_blanks={blanks:[],case_sensitive:false};c.blanks=[]}
  if(type==='sorting'){a.sorting={items:[],correct_order:[]};c.items=[]}
  if(type==='image_interaction')a.image_interaction={mode:'pin',asset:'',targets:[],...defaults};
  if(type==='draw_annotate')a.draw_annotate={asset:'',max_strokes:120,allow_text:true};
  if(type==='collaborative_board')a.collaborative_board={max_notes:5,max_characters:240,categories:['Board'],identity_visibility:'trainer_only',...defaults};
  if(type==='interactive_video')a.interactive_video={asset:'',checkpoints:[],pause_at_checkpoint:true,...defaults};
}

