  if(type==='sorting'){const items=a.sorting?.correct_order||a.sorting?.items||c.items||[];return section('Sorting settings',`<div class="field span-2"><label>${esc(t('Prompt'))}</label><input class="input" id="advQuestion" value="${esc(c.question||'')}"></div><div class="field span-2"><label>${esc(t('Correct order'))}</label><textarea class="textarea" id="advItems">${esc(items.join('\n'))}</textarea><small>${esc(t('Enter one item per line in the correct order.'))}</small></div>`)}
  if(type==='image_interaction'){const x={mode:'pin',targets:[],...(a.image_interaction||{})};return section('Image Interaction settings',`<div class="field"><label>${esc(t('Mode'))}</label><select class="select" id="advImageMode">${['pin','find','label','drag'].map(k=>`<option value="${k}" ${x.mode===k?'selected':''}>${esc(t(k))}</option>`).join('')}</select></div><div class="field"><label>${esc(t('Image asset path'))}</label><input class="input" id="advAsset" value="${esc(x.asset||c.image_asset||'')}"></div><div class="field"><label>${esc(t('Maximum answers'))}</label><input class="input" id="advMaxPoints" type="number" min="1" max="20" value="${Number(x.max_points||(x.targets||[]).length||1)}"></div><div class="field span-2"><label>${esc(t('Targets'))}</label><textarea class="textarea" id="advTargets" placeholder="Heart | 45 | 32 | 8">${esc((x.targets||[]).map(y=>`${y.label||''} | ${Number(y.x||0)} | ${Number(y.y||0)} | ${Number(y.tolerance||8)}`).join('\n'))}</textarea><small>${esc(t('label | x% | y% | tolerance%'))}</small></div>`)}
