async function validate(){await refreshReadiness();showValidation()}
function showValidation(){
 const issues=describeCourseIssues(state.content,state.readiness?.errors||[],state.readiness?.warnings||[]),ar=document.documentElement.lang==='ar';
 const wrap=modal(t('Validation details'),`<p>${esc(t('Drafts can be saved while incomplete. Publishing requires every blocker to be resolved.'))}</p><div class="validation-issues">${issues.map((issue,index)=>`<article class="validation-issue"><div class="metric-row"><strong dir="auto">${esc(issue.location)}</strong><span class="badge">${esc(t(issue.severity==='blocker'?'Blocker':'Warning'))}</span></div><h3>${esc(ar?issue.cause_ar:issue.cause)}</h3><p dir="auto">${esc(issue.detail)}</p><div class="validation-repair"><strong>${esc(t('How to resolve'))}</strong><p>${esc(ar?issue.fix_ar:issue.fix)}</p></div>${issue.selection?`<button class="btn" data-open-issue="${index}">${esc(t('Open affected item'))}</button>`:''}</article>`).join('')||`<div class="empty">${esc(t('Ready to publish'))}</div>`}</div>`,{onConfirm:null,wide:true});
 wrap.querySelectorAll('[data-open-issue]').forEach(button=>button.onclick=()=>{state.selection=issues[Number(button.dataset.openIssue)].selection;state.tab='edit';wrap.remove();render()});
}
function deleteMilestone(mi){
 const module=moduleAt(mi);if(!module)return;const dependencies=milestoneDependencies(state.content,mi);
 if(dependencies.length){const wrap=modal(t('Milestone is referenced'),`<p>${esc(t('Resolve these references before deleting this milestone.'))}</p><div class="list">${dependencies.map((d,i)=>`<div class="list-row"><strong dir="auto">${esc(d.title)}</strong>${d.mi!==null?`<button class="btn" data-open-dependency="${i}">${esc(t('Open affected item'))}</button>`:''}</div>`).join('')}</div>`,{onConfirm:null,wide:true});wrap.querySelectorAll('[data-open-dependency]').forEach(button=>button.onclick=()=>{state.selection={kind:'workflow',mi:dependencies[Number(button.dataset.openDependency)].mi};state.tab='edit';wrap.remove();render()});return}
 modal(t('Delete milestone'),`<h3 dir="auto">${esc(module.title||t('Untitled'))}</h3><p>${esc(t('This removes the milestone and its activities, missions, participant paths and workflow from this draft. Published versions remain in history.'))}</p><p>${(module.activities||[]).length} ${esc(t('Activities'))} · ${(module.missions||[]).length} ${esc(t('Missions'))} · ${(module.paths||[]).length} ${esc(t('Participant paths'))}</p>`,{confirmText:t('Delete milestone'),onConfirm:async()=>{remember();mods().splice(mi,1);state.selection=null;markDirty();await refreshReadiness();render()}});
}
async function importPresentation(){
  if(!state.version?.id||state.version?.status!=='draft')return toast(t('Presentation imports require a draft course version.'),'error');
  const input=document.createElement('input');input.type='file';input.accept='.pdf,.pptx,application/pdf,application/vnd.openxmlformats-officedocument.presentationml';
  input.onchange=async()=>{const file=input.files?.[0];if(!file)return;const lower=file.name.toLowerCase();if(!lower.endsWith('.pdf')&&!lower.endsWith('.pptx'))return toast(t('Choose a PDF or PPTX file.'),'error');
    try{const key=`assets/imported/${Date.now()}_${file.name.replace(/[^a-zA-Z0-9._-]+/g,'_')}`;const r=await api(`/api/course-versions/${state.version.id}/presentation-import`,{method:'POST',body:await file.arrayBuffer(),headers:{'X-File-Name':encodeURIComponent(file.name),'X-Asset-Key':key,'Content-Type':file.type||'application/octet-stream'}});const item=selected();item.content??={blocks:[]};item.content.blocks??=[];item.content.blocks.push(r.block);markDirty();render();toast(r.warnings?.length?`${t('Presentation imported.')} ${r.warnings.join(' ')}`:t('Presentation imported.'),'success')}catch(e){toast(e.message,'error')}};input.click();
}
