function arrOf(kind,mi){const m=moduleAt(mi);if(kind==='activity')return m.activities??=[];if(kind==='mission')return m.missions??=[];return m.paths??=[]}
function addItem(kind,mi){const a=arrOf(kind,mi);if(kind==='activity')a.push({id:`activity_${Date.now()}`,type:'presentation',title:'New activity',trainer:{cue:''},content:{blocks:[{type:'text',title:'',body_md:''}]},results_display:'cards'});else if(kind==='mission')a.push({id:`mission_${Date.now()}`,title:'New mission',goal:'',steps:[{id:'step_1',title:'Step 1',body_md:'',completion:{type:'acknowledge'}}],submission:{type:'none'}});else a.push({id:`path_${Date.now()}`,title:'New participant path',description:'',steps:[{id:'step_1',title:'Step 1',body_md:'',completion:{type:'acknowledge'}}]});state.selection={kind,mi,ii:a.length-1};state.tab='edit';markDirty();render()}
function moveItem(kind,mi,i,d){const a=arrOf(kind,mi),j=d==='up'?i-1:i+1;if(j>=0&&j<a.length)[a[i],a[j]]=[a[j],a[i]];markDirty();render()}
function copyItem(kind,mi,i){const a=arrOf(kind,mi),x=structuredClone(a[i]);x.id=`${x.id}_copy_${Date.now()}`;x.title=`${x.title||'Item'} copy`;a.splice(i+1,0,x);markDirty();render()}
function delItem(kind,mi,i){const m=moduleAt(mi),arr=arrOf(kind,mi),item=arr[i];if(!item)return;const id=String(item.id||''),wf=m?.workflow||{},refs=(wf.nodes||[]).filter(n=>String(kind==='activity'?n.activity_id:kind==='mission'?n.mission_id:n.path_id)===id).map(n=>n.id);const flowRefs=kind==='activity'?(m.activities||[]).filter(a=>String(a.flow?.next_activity_id||'')===id).map(a=>a.id):[];if(refs.length||flowRefs.length){toast(t('This item is still referenced by the workflow or another activity. Remove those dependencies first.'),'error');return}if(confirm(t('Delete this item?'))){arr.splice(i,1);markDirty();render()}}
function newBlock(type){if(type==='hero')return {type,title:'New title',body_md:''};if(['image','image_text','asset','video','audio','document','slide_deck','interactive_video'].includes(type))return {type,title:'',asset:'assets/'};if(type==='formula')return {type,title:'Formula',body_md:'\\frac{a}{b}'};if(type==='chart')return {type,chart_type:'horizontal_bar',title:'',data:[]};if(type==='timeline')return {type,title:'Timeline',items:[{title:'Step 1',body_md:''}]};if(type==='leaderboard')return {type,title:'Leaderboard',items:[]};if(type==='cards'||type==='steps'||type==='comparison'||type==='resource_list'||type==='gallery'||type==='checklist'||type==='table')return {type,title:'',items:[]};if(type==='statistic')return {type,title:'',value:'0',label:''};if(type==='quote')return {type,title:'',quote:'',attribution:''};if(type==='prompt')return {type,title:'Prompt',prompt:''};if(type==='editable_prompt')return {type,title:'Prompt',template:''};return {type,title:'',body_md:''}}
