function applyModule(){const m=selected();m.title=document.querySelector('#modTitle').value.trim()||m.title;m.duration_minutes=Math.max(0,Number(document.querySelector('#modDuration').value||0));m.description=document.querySelector('#modDescription').value;m.objectives=document.querySelector('#modObjectives').value.split(/\n/).map(x=>x.trim()).filter(Boolean).map((title,i)=>({id:`${m.id}_objective_${i+1}`,title}));markDirty();toast(t('Applied'),'success');render()}
function changeActivityType(){
  const a=selected();if(!a)return;
  remember();
  a.title=document.querySelector('#actTitle')?.value.trim()||a.title;
  a.trainer={...(a.trainer||{}),cue:document.querySelector('#actCue')?.value||''};
  collectBlockEdits(a);
  const type=document.querySelector('#actType')?.value||a.type||'presentation',spec=activitySpec(type),chosen=document.querySelector('#actResults')?.value||a.results_display||'';
  initializeActivityType(a,type,spec);
  if(spec?.results?.length)a.results_display=spec.results.length===1?spec.results[0]:(spec.results.includes(chosen)?chosen:spec.results[0]);else delete a.results_display;
  markDirtyWithoutAutosave();
  render();
}
function applyActivity(silent=false){const a=selected();a.title=document.querySelector('#actTitle').value.trim()||a.title;const type=document.querySelector('#actType').value;a.type=type;const chosenResult=document.querySelector('#actResults')?.value||a.results_display||'';const typeSpec=activitySpec(type);if(typeSpec?.results?.length)a.results_display=typeSpec.results.length===1?typeSpec.results[0]:(typeSpec.results.includes(chosenResult)?chosenResult:typeSpec.results[0]);else delete a.results_display;a.trainer={...(a.trainer||{}),cue:document.querySelector('#actCue').value};collectBlockEdits(a);applyGenericActivitySettings(a,type);if(type==='word_cloud'){a.content??={blocks:[]};const q=document.querySelector('#wcQuestion')?.value.trim();if(q)a.content.question=q;else if(!a.content.question)a.content.question=a.title;const prev={max_entries:3,max_characters:32,allow_phrases:true,moderation:'off',identity_visibility:'trainer_only',...(a.word_cloud||{})};a.word_cloud={max_entries:Math.max(1,Math.min(5,Number(document.querySelector('#wcMaxEntries')?.value||prev.max_entries||3))),max_characters:Math.max(8,Math.min(60,Number(document.querySelector('#wcMaxCharacters')?.value||prev.max_characters||32))),allow_phrases:document.querySelector('#wcAllowPhrases')?.checked??prev.allow_phrases,moderation:document.querySelector('#wcModeration')?.value||prev.moderation,identity_visibility:document.querySelector('#wcIdentity')?.value||prev.identity_visibility}}else if(a.word_cloud)delete a.word_cloud;if(type==='q_and_a'){a.content??={blocks:[]};const q=document.querySelector('#qaQuestion')?.value.trim();if(q)a.content.question=q;else if(!a.content.question)a.content.question=a.title;const prev={max_questions:3,max_characters:280,moderation:'pre',identity_visibility:'trainer_only',upvoting:true,allow_self_upvote:false,sort:'votes',...(a.q_and_a||{})};a.q_and_a={max_questions:Math.max(1,Math.min(5,Number(document.querySelector('#qaMaxQuestions')?.value||prev.max_questions||3))),max_characters:Math.max(40,Math.min(500,Number(document.querySelector('#qaMaxCharacters')?.value||prev.max_characters||280))),moderation:document.querySelector('#qaModeration')?.value||prev.moderation,identity_visibility:document.querySelector('#qaIdentity')?.value||prev.identity_visibility,upvoting:document.querySelector('#qaUpvoting')?.checked??prev.upvoting,allow_self_upvote:document.querySelector('#qaSelfUpvote')?.checked??prev.allow_self_upvote,sort:document.querySelector('#qaSort')?.value||prev.sort}}else if(a.q_and_a)delete a.q_and_a;if(type==='ideas_board'){a.content??={blocks:[]};const q=document.querySelector('#ibQuestion')?.value.trim();if(q)a.content.question=q;else if(!a.content.question)a.content.question=a.title;const prev={max_ideas:5,max_characters:240,moderation:'pre',identity_visibility:'trainer_only',upvoting:true,allow_self_upvote:false,sort:'votes',categories:['Ideas'],...(a.ideas_board||{})};const categories=(document.querySelector('#ibCategories')?.value||'').split(/\n/).map(x=>x.trim()).filter(Boolean).slice(0,6);a.ideas_board={max_ideas:Math.max(1,Math.min(8,Number(document.querySelector('#ibMaxIdeas')?.value||prev.max_ideas||5))),max_characters:Math.max(20,Math.min(500,Number(document.querySelector('#ibMaxCharacters')?.value||prev.max_characters||240))),moderation:document.querySelector('#ibModeration')?.value||prev.moderation,identity_visibility:document.querySelector('#ibIdentity')?.value||prev.identity_visibility,upvoting:document.querySelector('#ibUpvoting')?.checked??prev.upvoting,allow_self_upvote:document.querySelector('#ibSelfUpvote')?.checked??prev.allow_self_upvote,sort:document.querySelector('#ibSort')?.value||prev.sort,categories:categories.length?categories:prev.categories};}else if(a.ideas_board)delete a.ideas_board;if(['prioritization_100','quick_interaction','matching','fill_blanks','sorting','image_interaction','draw_annotate','collaborative_board','interactive_video'].includes(type))applyAdvancedActivity(a,type);const explanation=document.querySelector('#actExplanation')?.value||'';if(explanation)a.explanation=explanation;else delete a.explanation;a.challenge={enabled:document.querySelector('#actChallengeEnabled')?.checked===true,time_seconds:Math.max(0,Number(document.querySelector('#actChallengeSeconds')?.value||0)),points:Math.max(0,Number(document.querySelector('#actChallengePoints')?.value||0))};const next=document.querySelector('#actNext').value;a.flow=next?{...(a.flow||{}),next_activity_id:next}:{...(a.flow||{})};if(!next&&a.flow)delete a.flow.next_activity_id;const min=Number(document.querySelector('#actMinResponses').value||0);if(min>0)a.completion_gate={...(a.completion_gate||{}),minimum_responses:min};else if(a.completion_gate){delete a.completion_gate.minimum_responses;if(!Object.keys(a.completion_gate).length)delete a.completion_gate}markDirty();if(!silent)toast(t('Applied'),'success');render()}
function collectSteps(x){x.steps.forEach((st,i)=>{st.title=document.querySelector(`[data-step-title="${i}"]`)?.value||st.title;st.body_md=document.querySelector(`[data-step-body="${i}"]`)?.value||'';const pr=document.querySelector(`[data-step-prompt="${i}"]`)?.value||'';if(pr)st.prompt=pr;else delete st.prompt;st.completion={...(st.completion||{}),type:document.querySelector(`[data-step-completion="${i}"]`)?.value||'acknowledge'}})}
function applyMission(){const m=selected();m.title=document.querySelector('#missionTitle').value.trim()||m.title;m.goal=document.querySelector('#missionGoal').value;m.submission={...(m.submission||{}),type:document.querySelector('#missionSubmission').value};const ach=document.querySelector('#missionAchievement').value.trim();if(ach)m.achievement={key:m.achievement?.key||`achievement_${Date.now()}`,title:ach};else delete m.achievement;collectSteps(m);markDirty();toast(t('Applied'),'success');render()}
function applyPath(){const p=selected();p.title=document.querySelector('#pathTitle').value.trim()||p.title;p.description=document.querySelector('#pathDescription').value;p.offline_fallback=document.querySelector('#pathFallback').value;const ach=document.querySelector('#pathAchievement').value.trim();if(ach)p.achievement={key:p.achievement?.key||`achievement_${Date.now()}`,title:ach};else delete p.achievement;collectSteps(p);markDirty();toast(t('Applied'),'success');render()}
function autoWorkflow(){const m=moduleAt(state.selection.mi),wf=selected();wf.nodes=[];wf.edges=[];const classNodes=[];for(const a of m.activities||[]){const n={id:`wf_${a.id}`,type:activitySpec(a.type)?.participant_input?'class_interaction':'activity',title:a.title,activity_id:a.id};wf.nodes.push(n);classNodes.push(n)}for(let i=0;i<classNodes.length-1;i++)wf.edges.push({from:classNodes[i].id,to:classNodes[i+1].id,scope:'class'});let tail=classNodes.at(-1)||null;if((m.paths||[]).length){const practice={id:`wf_practice_${m.id}`,type:'practice_start',title:t('Start student activity')};wf.nodes.push(practice);if(tail)wf.edges.push({from:tail.id,to:practice.id,scope:'class'});const pathNodes=(m.paths||[]).map(pp=>({id:`wf_path_${pp.id}`,type:'participant_path',title:pp.title,path_id:pp.id}));wf.nodes.push(...pathNodes);for(const n of pathNodes)wf.edges.push({from:practice.id,to:n.id,scope:'participant',condition:{path_id:n.path_id}});const join={id:`wf_converge_${m.id}`,type:'convergence',title:t('Convergence')};wf.nodes.push(join);for(const n of pathNodes)wf.edges.push({from:n.id,to:join.id,scope:'participant'});tail=join}for(const x of m.missions||[]){const n={id:`wf_mission_${x.id}`,type:'mission',title:x.title,mission_id:x.id};wf.nodes.push(n);if(tail)wf.edges.push({from:tail.id,to:n.id,scope:'class'});tail=n}const close={id:`wf_close_${m.id}`,type:'closing',title:t('Closing')};wf.nodes.push(close);if(tail)wf.edges.push({from:tail.id,to:close.id,scope:'class'});wf.start_node_id=wf.nodes[0]?.id||'';markDirty();render()}
function applyWorkflow(){const wf=selected();wf.start_node_id=document.querySelector('#workflowStart').value;wf.nodes.forEach((n,i)=>{n.title=document.querySelector(`[data-wf-title="${i}"]`)?.value||n.title;n.type=document.querySelector(`[data-wf-type="${i}"]`)?.value||n.type;const aid=document.querySelector(`[data-wf-activity="${i}"]`)?.value||'',mid=document.querySelector(`[data-wf-mission="${i}"]`)?.value||'',pid=document.querySelector(`[data-wf-path="${i}"]`)?.value||'';if(aid)n.activity_id=aid;else delete n.activity_id;if(mid)n.mission_id=mid;else delete n.mission_id;if(pid)n.path_id=pid;else delete n.path_id;if(document.querySelector(`[data-wf-terminal="${i}"]`)?.checked)n.terminal=true;else delete n.terminal});wf.edges.forEach((e,i)=>{e.from=document.querySelector(`[data-wf-from="${i}"]`)?.value||e.from;e.to=document.querySelector(`[data-wf-to="${i}"]`)?.value||e.to;e.scope=document.querySelector(`[data-wf-scope="${i}"]`)?.value||'class';const c=parseConditionText(document.querySelector(`[data-wf-condition="${i}"]`)?.value||'');if(c)e.condition=c;else delete e.condition});markDirty();toast(t('Applied'),'success');render()}
